54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    private final OwnerRequestValidator ownerRequestValidator;
73	
74	    private final HouseholdDuplicateValidator householdDuplicateValidator;
75	
76	    private final TelephoneNormalizer telephoneNormalizer;
77	
78	    private final EmailNormalizer emailNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    private final CustomerCodeGenerator customerCodeGenerator;
83	
84	    private final HouseholdRegistrar householdRegistrar;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper,
90	                                 OwnerRequestValidator ownerRequestValidator,
91	                                 HouseholdDuplicateValidator householdDuplicateValidator,
92	                                 TelephoneNormalizer telephoneNormalizer,
93	                                 EmailNormalizer emailNormalizer,
94	                                 AddressNormalizer addressNormalizer,
95	                                 CustomerCodeGenerator customerCodeGenerator,
96	                                 HouseholdRegistrar householdRegistrar) {
97	        this.clinicService = clinicService;
98	        this.ownerMapper = ownerMapper;
99	        this.petMapper = petMapper;
100	        this.visitMapper = visitMapper;
101	        this.ownerRequestValidator = ownerRequestValidator;
102	        this.householdDuplicateValidator = householdDuplicateValidator;
103	        this.telephoneNormalizer = telephoneNormalizer;
104	        this.emailNormalizer = emailNormalizer;
105	        this.addressNormalizer = addressNormalizer;
106	        this.customerCodeGenerator = customerCodeGenerator;
107	        this.householdRegistrar = householdRegistrar;
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
113	        Collection<Owner> owners;
114	        if (lastName != null) {
115	            owners = this.clinicService.findOwnerByLastName(lastName);
116	        } else {
117	            owners = this.clinicService.findAllOwners();
118	        }
119	        if (owners.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
139	        this.ownerRequestValidator.validate(ownerFieldsDto);
140	        this.householdDuplicateValidator.validate(ownerFieldsDto);
141	        String telephone = this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
142	        ownerFieldsDto.setTelephone(telephone);
143	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
144	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
145	            throw new DuplicateTelephoneException(telephone);
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        owner.setCustomerCode(
150	            this.customerCodeGenerator.generate(owner.getLastName(), this.clinicService.countOwners()));
151	        owner.setNamesakeCount(
152	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
153	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
154	            this.householdRegistrar.register(owner);
155	        }
156	        this.clinicService.saveOwner(owner);
157	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        currentOwner.setAddress(ownerFieldsDto.getAddress());
171	        currentOwner.setCity(ownerFieldsDto.getCity());
172	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
173	        currentOwner.setLastName(ownerFieldsDto.getLastName());
174	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
175	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
176	        this.clinicService.saveOwner(currentOwner);
177	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Transactional
182	    @Override
183	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        this.clinicService.deleteOwner(owner);
189	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
